// Calcucrypt's frontend names its server types through the global `App.Data.*` / `App.Enums.*`
// namespaces. This starter's TypeScript transformer writes ES modules instead
// (`resources/js/generated/App/*`, regenerated by `composer types:generate`). Each line below only
// points a global name at its generated module, so a shape is never typed by hand: change the PHP
// Data class and regenerate, and every page sees the change.

declare namespace App.Data {
    type CalculatorEmbedData = import('@/generated/App/Data').CalculatorEmbedData;
    type CalculatorResolutionData = import('@/generated/App/Data').CalculatorResolutionData;
    type CalculatorSpecData = import('@/generated/App/Data').CalculatorSpecData;
    type CalculatorSummaryData = import('@/generated/App/Data').CalculatorSummaryData;
    type FactData = import('@/generated/App/Data').FactData;
    type GuideData = import('@/generated/App/Data').GuideData;
    type GuideSummaryData = import('@/generated/App/Data').GuideSummaryData;
}

declare namespace App.Enums {
    type AssociationMode = import('@/generated/App/Enums').AssociationMode;
    type CalculatorStatus = import('@/generated/App/Enums').CalculatorStatus;
    type NodeKind = import('@/generated/App/Enums').NodeKind;
}
